public class BackgroundProcessor : IDisposable
{
    private Thread? _workerThread;
    private CancellationTokenSource? _cts;

    public void Start()
    {
        _cts = new CancellationTokenSource();
        var token = _cts.Token;
        _workerThread = new Thread(() => ProcessLoop(token));
        _workerThread.IsBackground = true;
        _workerThread.Start();
    }

    private void ProcessLoop(CancellationToken token)
    {
        while (!token.IsCancellationRequested)
        {
            try
            {
                var item = GetNextItem(token); // pass token so blocking calls can unblock
                ProcessItem(item, token);
            }
            catch (OperationCanceledException) when (token.IsCancellationRequested)
            {
                // Clean up partial work — replaces ThreadAbortException catch
                RollbackCurrentTransaction();
                // No ResetAbort needed — we control whether the loop continues
                // via the while condition. Loop exits naturally.
            }
            finally
            {
                FlushBuffers();
            }
        }
    }

    public void Stop()
    {
        if (_cts is null) return;

        _cts.Cancel(); // signals cooperative cancellation (replaces Thread.Abort)

        // Wait up to 2 seconds for graceful shutdown
        _workerThread?.Join(TimeSpan.FromMilliseconds(2000));
        // If thread is still alive after Join, it's a background thread
        // and will be torn down on process exit. No force-kill equivalent
        // exists in modern .NET for managed threads.
    }

    public void Dispose()
    {
        Stop();
        _cts?.Dispose();
        _cts = null;
    }
}
